package io.github.dream07code.innovationspace.scoring;
import java.net.URI;import java.net.http.*;import java.time.Duration;import tools.jackson.databind.json.JsonMapper;
public class OpenAiCompatibleReportScoringProvider implements ReportScoringProvider {private final ScoringProperties p;private final HttpClient client;private final JsonMapper json=JsonMapper.builder().build();public OpenAiCompatibleReportScoringProvider(ScoringProperties p){this.p=p;p.validate();this.client=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(p.getConnectTimeoutMs())).build();}
 public ProviderScore score(ScoringInput input){try{var body=json.writeValueAsString(java.util.Map.of("model",p.getModel(),"messages",java.util.List.of(java.util.Map.of("role","user","content","Report type: "+input.reportType()+"\nRubric: "+input.rubricVersion()+"\nContent:\n"+input.content()))));var request=HttpRequest.newBuilder(URI.create(p.getBaseUrl().replaceAll("/$","")+"/v1/chat/completions")).timeout(Duration.ofMillis(p.getRequestTimeoutMs())).header("Authorization","Bearer "+p.getApiKey()).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build();var response=client.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()/100!=2)throw new IllegalStateException("AI provider request failed");var root=json.readTree(response.body());var content=root.at("/choices/0/message/content").asText();var score=json.readTree(content);var result=new ProviderScore(score.path("score").asInt(-1),score.path("reason").asText(null),p.getProvider(),p.getModel());result.validate();return result;}catch(ProviderScoreException e){throw e;}catch(Exception e){throw new ProviderScoreException("AI provider unavailable",e);}}
 public static class ProviderScoreException extends RuntimeException{public ProviderScoreException(String m,Throwable c){super(m,c);}}
}
